<header class="site-header"><div class="wrap head"><a class="brand" href="/"><?= e($siteName) ?></a><button class="mobile-menu-toggle" id="menuToggle" aria-label="Menüyü aç" aria-expanded="false">☰</button><nav class="nav" id="siteNavigation"><?php foreach($navigation as $item): ?><a href="<?= e($item['url']) ?>" target="<?= e($item['target']) ?>" <?= $item['target']==='_blank'?'rel="noopener noreferrer"':'' ?>><?= e($item['label']) ?></a><?php endforeach; ?><a href="/konaklamalar">Konaklamalar</a><?php if(($mode??'single_vendor')==='multi_vendor'): ?><a class="nav-cta" href="/vendor/register">Ev sahibi olun</a><?php endif; ?><?php if(($user['role']??'')==='customer'): ?><a href="/favorites">Favorilerim</a><a href="/account/bookings">Hesabım</a><?php endif; ?></nav></div></header><div class="drawer-overlay" id="menuOverlay"></div>
<main class="home-sections"><?php if($active('hero')): ?><section class="hero" style="order:<?= $order('hero',1) ?>"><div class="wrap"><div class="hero-card" style="<?= !empty($homeSections['hero']['image_url'])?'background-image:linear-gradient(90deg,rgba(14,40,37,.7),rgba(14,40,37,.05)),url('.e($homeSections['hero']['image_url']).')':'' ?>"><div class="hero-copy"><span class="eyebrow"><?= e($content['home_eyebrow']??'TATİLİNİZİ GÜZELLEŞTİRİN') ?></span><h1><?= e($content['home_title']??'Hayalinizdeki tatil sizi bekliyor') ?></h1><p><?= e($content['home_subtitle']??'Deniz, doğa ve huzur… Size en uygun tatil evini keşfedin.') ?></p><form class="search" action="/konaklamalar" method="get"><input type="text" name="city" placeholder="Nereye gitmek istersiniz?" aria-label="Destinasyon"><select name="guests"><option value="">Misafir sayısı</option><?php for($i=1;$i<=16;$i++): ?><option value="<?= $i ?>"><?= $i ?> misafir</option><?php endfor; ?></select><button type="submit">Tatilimi keşfet ↗</button></form></div></div></div></section><?php endif; ?>
<?php if($active('destinations')): ?><section class="section" style="order:<?= $order('destinations',2) ?>"><div class="wrap"><div class="section-head"><div><span class="pill">KEŞFETMEYE BAŞLA</span><h2><?= e($homeSections['destinations']['title']??'Popüler destinasyonlar') ?></h2><p><?= e($homeSections['destinations']['subtitle']??'Türkiye’nin en sevilen tatil rotalarında size özel konaklamalar.') ?></p></div><a class="more" href="/destinasyonlar">Tüm destinasyonlar →</a></div><div class="destination-grid"><?php foreach($destinations as $d): $img=$photo($d); ?><a class="destination" href="/konaklamalar?<?= e(http_build_query(['city'=>$d['city']])) ?>"><?php if($img): ?><img src="<?= e($img) ?>" alt="<?= e($d['city']) ?>" loading="lazy"><?php else: ?><img src="<?= e($stylePhotos[0]) ?>" alt="<?= e($d['city']) ?>" loading="lazy"><?php endif; ?><span class="destination-label"><strong><?= e($d['city']) ?></strong><small><?= (int)$d['property_count'] ?> konaklama</small></span></a><?php endforeach; ?></div></div></section><?php endif; ?>
<?php if($active('featured')): ?><section class="section" style="order:<?= $order('featured',3) ?>;background:#fbfaf7"><div class="wrap"><div class="section-head"><div><span class="pill">SİZİN İÇİN SEÇTİK</span><h2><?= e($homeSections['featured']['title']??'En çok tercih edilen konaklamalar') ?></h2><p><?= e($homeSections['featured']['subtitle']??'Misafirlerin keşfetmeyi seveceği özel tatil evleri.') ?></p></div><a class="more" href="/konaklamalar">Tüm konaklamalar →</a></div><div class="cards"><?php foreach($featuredProperties as $p): $img=$photo($p); ?><a class="stay" href="/villa/<?= e($p['slug']) ?>"><div class="stay-photo"><?php if($img): ?><img src="<?= e($img) ?>" alt="<?= e($p['title']) ?>" loading="lazy"><?php endif; ?></div><h3><?= e($p['title']) ?></h3><div class="muted"><?= e(trim(($p['district']??'').', '.($p['city']??''))) ?> · <?= (int)$p['max_guests'] ?> misafir</div><div class="stay-price"><strong><?= e(number_format((float)$p['base_nightly_price'],0,',','.')) ?> <?= e($p['currency']) ?></strong> / gece</div></a><?php endforeach; ?></div></div></section><?php endif; ?>
<?php if($active('styles')): ?><section class="section" style="order:<?= $order('styles',4) ?>"><div class="wrap"><div class="section-head"><div><span class="pill">TATİL TARZINI SEÇ</span><h2><?= e($homeSections['styles']['title']??'Nasıl bir tatil hayal ediyorsunuz?') ?></h2><p><?= e($homeSections['styles']['subtitle']??'Size en yakın tatil deneyimini seçin.') ?></p></div></div><div class="styles"><?php $styleNames=['Havuz başında keyif','Modern ve lüks villalar','Ailece huzurlu tatil','Doğayla baş başa']; foreach($styleNames as $i=>$name): ?><a class="style-card" href="/konaklamalar"><img src="<?= e($stylePhotos[$i]) ?>" alt="<?= e($name) ?>" loading="lazy"><strong><?= e($name) ?> ↗</strong></a><?php endforeach; ?></div></div></section><?php endif; ?>
<?php if($active('gallery')): ?><section class="section" style="order:<?= $order('gallery',5) ?>;background:#f7f5ef"><div class="wrap"><div class="section-head"><div><span class="pill">TATİL İLHAMIN</span><h2><?= e($homeSections['gallery']['title']??'Biraz hayal kurmaya ne dersiniz?') ?></h2><p><?= e($homeSections['gallery']['subtitle']??'Güne güzel bir manzarayla başlayın, gün batımını kendi terasınızdan izleyin.') ?></p></div></div><div class="gallery-strip"><img src="<?= e($stylePhotos[0]) ?>" alt="Havuzlu tatil villası" loading="lazy"><img src="<?= e($stylePhotos[1]) ?>" alt="Modern tatil evi" loading="lazy"><img src="<?= e($stylePhotos[2]) ?>" alt="Villa iç mekânı" loading="lazy"><img src="<?= e($stylePhotos[3]) ?>" alt="Tatil villası" loading="lazy"></div></div></section><?php endif; ?>
<?php if(($mode??'single_vendor')==='multi_vendor' && $active('hosts')): ?><section class="wrap" style="order:<?= $order('hosts',6) ?>"><div class="host-banner"><div class="host-copy"><h2><?= e($homeSections['hosts']['title']??'Villanızı binlerce tatilseverle buluşturun') ?></h2><p><?= e($homeSections['hosts']['subtitle']??'Konaklamanızı yayınlayın, takviminizi yönetin ve yeni misafirlere ulaşın.') ?></p><a href="/vendor/register">Ev sahibi olarak katılın ↗</a></div></div></section><?php endif; ?>
</main>
<footer><div class="wrap footer-inner"><div class="footer-copy"><strong><?= e($siteName) ?></strong><p><?= e($content['footer_text']??'Hayalinizdeki tatil için doğru konaklama, doğru başlangıç.') ?></p></div><nav class="footer-links"><?php foreach($footerNavigation as $item): ?><a href="<?= e($item['url']) ?>"><?= e($item['label']) ?></a><?php endforeach; ?><a href="/konaklamalar">Konaklamalar</a></nav></div></footer>
<script>(function(){var b=document.getElementById('menuToggle'),n=document.getElementById('siteNavigation'),o=document.getElementById('menuOverlay');if(!b||!n||!o)return;function close(){n.classList.remove('is-open');o.classList.remove('is-open');document.body.classList.remove('menu-open');b.textContent='☰';b.setAttribute('aria-expanded','false')}b.addEventListener('click',function(){var open=!n.classList.contains('is-open');n.classList.toggle('is-open',open);o.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);b.textContent=open?'×':'☰';b.setAttribute('aria-expanded',open?'true':'false')});o.addEventListener('click',close);n.addEventListener('click',function(e){if(e.target.closest('a'))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(window.innerWidth>600)close()})})();</script></body></html>